    id: "loop_0123456789",
    sessionId: "session-1",
    projectKey: "project-1",
    directory: "/tmp",
    mode: "goal",
    status: "active",
    prompt: "Complete the objective",
    objective: "Complete the objective",
    steeringNotes: [],
    agent: null,
    providerId: null,
    modelId: null,
    variant: null,
    completion: { type: "agent" },
    intervalMs: null,
    cadenceAnchorAt: null,
    nextRunAt: 2_000,
    lastRunStartedAt: 1_000,
    lastRunFinishedAt: null,
    createdAt: 1_000,
    updatedAt: 1_000,
    expiresAt: 100_000,
    runCount: 1,
    maxRuns: 25,
    missedRunCount: 0,
    consecutiveFailureCount: 0,
    consecutiveNoProgressCount: 0,
    permissionBlocked: false,
    userInterruptedAt: null,
    inflightLease: null,
    lastResult: null,
    lastError: null,
    completionEvidence: null,
    blocker: null,
    stopReason: null,
